// ❌ OLD: In Next.js 14, fetch was cached by default unless specified.
// This led to accidental stale data for dynamic queries.
export async function getStats() {
  const res = await fetch('https://api.example.com/stats');
  return res.json();
}

import { cacheLife, cacheTag } from 'next/cache';

// ✅ NEW: Explicit caching boundary with lifecycle control
export async function getStats() {
  'use cache';
  cacheLife('hours');
  cacheTag('analytics');

  const res = await fetch('https://api.example.com/stats');
  return res.json();
}
